insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 3, 5, 'De fato, Moisés foi fiel como servo em toda a casa de Deus, para testemunho das coisas que haviam de ser ditas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 3, 6, 'mas Cristo [é fiel] como Filho sobre a sua casa. E nós somos sua casa, se até o fim mantivermos firmes a confiança e o orgulho da [nossa] esperança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 3, 7, 'Portanto, como diz o Espírito Santo: Hoje, se ouvirdes a sua voz,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 3, 8, 'não endureçais os vossos corações, como na provocação, no dia da tentação no deserto;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 3, 9, 'onde os vossos pais me tentaram, me provaram, e viram as minhas obras por quarenta anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 3, 10, 'Por isso me indignei contra essa geração, e disse: “Eles sempre se desviam nos corações, e não conheceram os meus caminhos”;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 3, 11, 'Então jurei na minha ira: “Eles não entrarão no meu repouso”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 3, 12, 'Cuidado, irmãos, para que nunca haja em algum de vós coração mau e infiel, que se afaste do Deus vivo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 3, 13, 'Em vez disso, encorajai-vos uns aos outros a cada dia, durante o tempo chamado “hoje”; a fim de que nenhum de vós se endureça pelo engano do pecado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 3, 14, 'Pois nós temos nos tornado participantes de Cristo, se, de fato, mantivermos firme a confiança do princípio até o fim;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 3, 15, 'como é dito: Hoje, se ouvirdes a sua voz, não endureçais os vossos corações, como na provocação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 3, 16, 'Porque alguns, mesmo ouvindo, provocaram-no [à ira] , mas não todos aqueles que saíram do Egito por meio de Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 3, 17, 'E contra quais ele se indignou por quarenta anos? Não foi contra os que pecaram, cujos corpos caíram no deserto?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 3, 18, 'E a quem ele jurou que não entrariam no seu repouso, senão aos que foram desobedientes?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 3, 19, 'Assim vemos que não puderam entrar por causa da incredulidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 4, 1, 'Temamos, pois, para que, havendo sido deixada a promessa de entrar no seu repouso, não pareça que algum de vós tenha ficado para trás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 4, 2, 'Pois também a nós foi pregado o evangelho, assim como a eles; mas a palavra da pregação nada lhes aproveitou, porque não estava combinada com a fé naqueles que [a] ouviram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 4, 3, 'Porque nós, os que cremos, entramos no repouso, como ele disse: Então jurei na minha ira: “Eles não entrarão no meu repouso”; ainda que as [suas] obras já estivessem terminadas desde a fundação do mundo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 4, 4, 'Pois, em certo lugar, ele disse assim a respeito do [dia] sétimo: E Deus repousou no sétimo dia de todas as suas obras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 4, 5, 'E, outra vez neste [texto] : Não entrarão no meu repouso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 4, 6, 'Portanto, uma vez que resta alguns entrarem no repouso, e que aqueles a quem primeiramente foi pregado o evangelho não entraram por causa da desobediência,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 4, 7, 'outra vez ele determina um certo dia, o “hoje”, dizendo por meio de Davi muito tempo depois (como já foi dito): Hoje, se ouvirdes a sua voz, não endureçais os vossos corações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 4, 8, 'Pois se Josué tivesse lhes dado repouso, ele não teria falado depois a respeito de outro dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 4, 9, 'Portanto, ainda resta um repouso como o do sábado para o povo de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 4, 10, 'Pois aquele que entrou no seu repouso também repousou das suas obras, assim como Deus das suas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 4, 11, 'Procuremos, pois, entrar naquele repouso; para que ninguém caia no mesmo exemplo de desobediência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 4, 12, 'Porque a palavra de Deus é viva e eficaz, e mais afiada do que toda espada de dois gumes, e que penetra até a divisão da alma e do espírito, das juntas e das medulas, e é apta para julgar os pensamentos e intenções do coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 4, 13, 'E não há criatura alguma encoberta diante dele; pelo contrário, todas as coisas estão nuas e expostas aos olhos daquele a quem temos de prestar contas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 4, 14, 'Visto que temos um grande Sumo Sacerdote, Jesus, o Filho de Deus, que penetrou nos céus, mantenhamos firme a [nossa] declaração de fé.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 4, 15, 'Pois não temos um Sumo Sacerdote que não possa se compadecer das nossas fraquezas; mas, sim, um que foi provado em tudo, conforme a [nossa] semelhança, [porém] sem pecado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 4, 16, 'Portanto, acheguemo-nos com confiança ao trono da graça, para que possamos receber misericórdia e encontrar graça para sermos socorridos no tempo adequado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 5, 1, 'Pois todo sumo sacerdote tomado dentre os homens é constituído em prol das pessoas nas coisas [relativas] a Deus, para apresentar tanto ofertas como sacrifícios pelos pecados;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 5, 2, 'e ele é capaz de se compadecer dos ignorantes e dos errados, pois ele mesmo também está rodeado de fraqueza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 5, 3, 'E, por causa desta [fraqueza] ,ele tem o dever de apresentar oferenda, tanto pelos pecados do povo, como também de si mesmo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 5, 4, 'E ninguém toma para si esta honra, a não ser aquele que é chamado por Deus, como Arão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 5, 5, 'Assim também Cristo não glorificou a si mesmo para se fazer Sumo Sacerdote; mas sim, àquele que lhe disse: Tu és meu Filho, eu hoje te gerei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 5, 6, 'Como também diz em outro [texto] : Tu és Sacerdote para sempre, segundo a ordem de Melquisedeque.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 5, 7, 'Ele, nos dias de seu corpo carnal, ofereceu com grande clamor e lágrimas, tanto orações como súplicas para aquele que podia o livrar da morte, e foi ouvido por causa da devoção.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 5, 8, 'Ainda que ele era o Filho, aprendeu a obediência por meio das coisas que sofreu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 5, 9, 'E, depois de ter sido consumado, ele foi feito autor da eterna salvação a todos os que lhe obedecem;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 5, 10, 'e nomeado por Deus como Sumo Sacerdote, segundo a ordem de Melquisedeque.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 5, 11, 'Nosso comentário a respeito disso é extenso e difícil de explicar, porque vos tornastes negligentes para ouvir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 5, 12, 'Pois, pelo tempo, vós já devíeis ser mestres; porém novamente tendes necessidade de serdes ensinados os princípios básicos das palavras de Deus; e vos fizestes como se precisásseis de leite, e não de alimento sólido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 5, 13, 'Pois qualquer um que depende de leite é inexperiente na palavra da justiça; porque [ainda] é um bebê.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 5, 14, 'Mas o alimento sólido é para os maduros, os quais, pelo costume, têm os sentidos treinados para discernirem tanto o bem como o mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 6, 1, 'Portanto deixemos os tópicos elementares da doutrina de Cristo, e prossigamos adiante até a maturidade, sem lançarmos de novo o fundamento da conversão de obras mortas, e da fé em Deus,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 6, 2, 'da doutrina dos batismos, da imposição das mãos, da ressurreição dos mortos, e do juízo eterno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 6, 3, 'E isso faremos, se Deus permitir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 6, 4, 'Pois é impossível que os que uma vez foram iluminados, e experimentaram o dom celestial, e foram feitos participantes do Espírito Santo,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 6, 5, 'e experimentaram a boa palavra de Deus, e os poderes do mundo futuro;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 6, 6, 'e então caíram, outra vez renová-los para o arrependimento, porque estão novamente crucificando o Filho de Deus para si mesmos, e o expondo à vergonha pública.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 6, 7, 'Pois a terra que absorve a chuva que com frequência vem sobre ela, e produz vegetação proveitosa para aqueles por quem e lavrada, recebe a bênção de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 6, 8, 'Contudo, se ela produz espinhos e cardos, é reprovada, e perto está da maldição. O seu fim é ser queimada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 6, 9, 'Mas, ainda que estejamos falando assim, quanto a vós mesmos, amados, confiamos melhores coisas, relacionadas à salvação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 6, 10, 'Pois Deus não é injusto para se esquecer da vossa obra, e do trabalho do amor que mostrastes para com o nome dele, quando servistes aos santos, e continuais a servir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 6, 11, 'Mas desejamos que cada um de vós mostre o mesmo empenho até o fim, para que a [vossa] esperança seja completa;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 6, 12, 'a fim de que não vos torneis negligentes, mas sim, imitadores dos que pela fé e pela paciência herdam as promessas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 6, 13, 'Pois Deus, quando prometeu a Abraão, como ninguém maior havia por quem jurar, jurou por si mesmo,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 6, 14, 'dizendo: Certamente muito te abençoarei, e muito te multiplicarei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 6, 15, 'E assim, esperando pacientemente, [Abraão] obteve a promessa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 6, 16, 'Pois as pessoas juram por alguém maior, e o juramento como confirmação é o fim de todo conflito entre elas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 6, 17, 'Assim Deus, querendo mostrar mais abundantemente a imutabilidade de sua intenção aos herdeiros da promessa, garantiu com um juramento;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 6, 18, 'a fim de que, por meio de duas coisas imutáveis, nas quais é impossível que Deus minta, nós, que buscamos refúgio, tenhamos encorajamento para agarrar a esperança posta diante [de nós] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 6, 19, 'Temos essa esperança como uma segura e firme âncora da alma, que entra ao interior, além do véu,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 6, 20, 'onde, [como] precursor, Jesus entrou para nosso benefício, pois ele se tornou Sumo Sacerdote para sempre, segundo a ordem de Melquisedeque.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 7, 1, 'Porque este Melquisedeque, rei de Salém, sacerdote do Deus Altíssimo, o qual se encontrou com Abraão, que estava retornando da matança dos reis, e o abençoou;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 7, 2, 'a quem também Abraão deu o dízimo de tudo; primeiramente significa Rei de justiça, e depois também rei de Salém, que é, rei de paz;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 7, 3, 'sem pai, sem mãe, sem genealogia, sem ter princípio de dias, nem fim de vida; porém, sendo feito semelhante ao Filho de Deus, permanece sacerdote para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 7, 4, 'Considerai, pois, como ele era grande, a quem até o patriarca Abraão deu o dízimo dos despojos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 7, 5, 'E, realmente, os que dentre os filhos de Levi recebem o sacerdócio têm ordem, segundo a Lei, de receberem os dízimos do povo, isto é, dos seus irmãos, mesmo sendo eles também descendentes de Abraão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 7, 6, 'Mas aquele que não é contado na genealogia deles recebeu dízimos de Abraão, e abençoou ao que tinha as promessas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 7, 7, 'Ora, sem contradição alguma, o menor é abençoado pelo maior.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 7, 8, 'Em um caso, homens mortais recebem dízimos; mas no outro, aquele de quem se dá testemunho de que vive.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 7, 9, 'E, por assim dizer, até Levi, que recebe os dízimos, pagou dízimos através de Abraão;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 7, 10, 'pois ele ainda estava no corpo de [seu] ancestral quando Melquisedeque se encontrou com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 7, 11, 'Portanto, se a perfeição tivesse sido de fato pelo sacerdócio Levítico (pois sob ele o povo recebeu a Lei), que mais necessidade havia de se levantar outro Sacerdote segundo a ordem de Melquisedeque, e não ser chamado segundo a ordem de Arão?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 7, 12, 'Pois, ao se mudar o sacerdócio, necessariamente também se faz mudança de Lei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 7, 13, 'Porque aquele de quem estas coisas são ditas pertence a outra tribo, da qual ninguém serviu ao altar;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 7, 14, 'visto ser evidente que o nosso Senhor é procedente de Judá, tribo da qual Moisés nada falou a respeito de sacerdócio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 7, 15, 'E [isso] ainda é muito mais evidente se, à semelhança de Melquisedeque, levanta-se outro sacerdote,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 7, 16, 'que foi constituído, não conforme a Lei de um mandamento carnal, mas sim, conforme o poder de uma vida indestrutível.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 7, 17, 'Pois [assim] ele dá testemunho: Tu és Sacerdote para sempre, segundo a ordem de Melquisedeque.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 7, 18, 'Porque há uma revogação do mandamento anterior, por causa da sua fraqueza e inutilidade,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 7, 19, 'pois a Lei não tornou perfeito nada. Porém, uma esperança melhor é introduzida, e por meio dela nos aproximamos de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 7, 20, 'E isso não foi [feito] sem juramento (pois os outros se tornaram sacerdotes sem juramento,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 7, 21, 'mas ele [foi estabelecido] com um juramento daquele que lhe disse: O Senhor jurou, e não se arrependerá: Tu és Sacerdote para sempre, segundo a ordem de Melquisedeque).'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 7, 22, 'Assim, Jesus foi feito fiador de um pacto ainda melhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 7, 23, 'Dos outros, são muitos os que se tornaram sacerdotes, pois pela morte foram impedidos de continuar;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 7, 24, 'mas ele, porque permanece para sempre, tem um sacerdócio definitivo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 7, 25, 'Portanto, ele também pode salvar de maneira completa os que se aproximam de Deus por meio dele, visto que ele vive para sempre para interceder por eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 7, 26, 'Pois nos era conveniente tal Sumo Sacerdote: santo, inocente, incontaminado, separado dos pecadores, e feito mais elevado que os céus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 7, 27, 'que não precisasse, como os sumos sacerdotes, de oferecer sacrifícios diariamente, primeiramente pelos seus próprios pecados, e depois pelos do povo. Pois ele fez isto de uma vez por todas quando ofereceu a si mesmo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 7, 28, 'Porque a Lei constitui por sumos sacerdotes homens que têm fraqueza; mas a palavra do juramento, que [veio] depois da Lei, [constitui] o Filho, que se tornou perfeito para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 8, 1, 'Ora, o ponto-chave do que falamos é que temos um Sumo Sacerdote que está sentado à direita do trono da Majestade nos céus,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 8, 2, 'servidor do Santuário, e do verdadeiro Tabernáculo, que Senhor ergueu, e não o homem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 8, 3, 'Pois todo sumo sacerdote é constituído para apresentar tanto ofertas como sacrifícios; por isso era necessário que também este tivesse alguma coisa a oferecer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 8, 4, 'Mas, se ele [ainda] estivesse na terra, nem sequer seria sacerdote, já que [ainda] há os sacerdotes que apresentam as ofertas segundo a Lei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 8, 5, 'Esses servem a um esboço, uma sombra das coisas celestiais, como Moisés foi divinamente avisado, antes de construir o Tabernáculo. Porque [Deus] disse: Olha, faze tudo conforme o modelo que te foi mostrado no monte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 8, 6, 'Mas agora [Jesus] obteve um ofício mais relevante, como é também Mediador de um melhor pacto, que está firmado em melhores promessas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 8, 7, 'Pois, se aquele primeiro tivesse sido infalível, nunca haveria se buscado lugar para o segundo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 8, 8, 'Porque, enquanto [Deus] repreendia os do povo, disse-lhes: Eis que vêm dias, diz o Senhor, que, sobre o povo de Israel e sobre o povo de Judá, estabelecerei um novo pacto;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 8, 9, 'não conforme o pacto que fiz com os seus ancestrais no dia em que eu os tomei pelas mãos, para os tirar da terra do Egito. Pois não permaneceram naquele meu pacto, e parei de lhes dar atenção, diz o Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 8, 10, 'Este, pois, é o pacto que farei com o povo de Israel depois daqueles dias, diz o Senhor: Porei minhas leis nas mentes deles, e as escreverei em seus corações. Eu serei o Deus deles, e eles serão o meu povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 8, 11, 'E não terão de ensinar cada um ao seu próximo, ou ao seu irmão, dizendo: “Conhece ao Senhor”; porque todos me conhecerão, desde o menor deles até o maior.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 8, 12, 'Pois serei misericordioso com as suas injustiças, e não mais me lembrarei dos seus pecados e das suas transgressões.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 8, 13, 'Quando ele disse: “Novo [pacto] ”, ele tornou o primeiro ultrapassado. Ora, o que se torna ultrapassado e envelhece está perto de desaparecer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 9, 1, 'O primeiro [pacto] também tinha ordenanças de culto, e o santuário terrestre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 9, 2, 'Pois um tabernáculo foi preparado, o primeiro, em que havia o candelabro, a mesa, e os pães da proposição. Esse é chamado o Santo Lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 9, 3, 'Mas após o segundo véu estava o tabernáculo que se chama Santo dos Santos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 9, 4, 'que tinha o incensário de ouro, e a arca do pacto, toda coberta de ouro. Nela estavam: o vaso de ouro contendo o maná, a vara de Arão que florescera, e as tábuas do pacto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 9, 5, 'E acima dela, os querubins de glória, que faziam sombra ao propiciatório. Acerca dessas coisas não [é oportuno] agora falar em detalhes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 9, 6, 'Ora, estando estas coisas assim preparadas, os sacerdotes entram a todo tempo no primeiro tabernáculo, para cumprirem as atividades de culto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 9, 7, 'Mas no segundo, somente o sumo sacerdote, uma vez por ano, não sem sangue, que oferece por si mesmo, e pelos pecados de ignorância do povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 9, 8, 'Desta maneira, o Espírito Santo dá a entender que o caminho para o Santuário não havia sido revelado enquanto o primeiro Tabernáculo ainda estava de pé.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 9, 9, 'Esse é uma figura para o tempo presente, em que são oferecidos ofertas e sacrifícios que não podem, quanto a consciência, tornar perfeito a quem faz o serviço;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 9, 10, '[pois consistem] somente em comidas e bebidas, e vários lavamentos, e ordenanças para o corpo, que foram impostas até o tempo da correção.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 9, 11, 'Mas quando veio Cristo, o Sumo Sacerdote dos bens futuros, por meio de um Tabernáculo maior e mais perfeito, não feito por mãos, isto é, não desta criação;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 9, 12, 'ele entrou de uma vez por todas no Santuário, e obteve uma redenção eterna, não pelo sangue de bodes e bezerros, mas sim, pelo seu próprio sangue.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 9, 13, 'Pois, se o sangue de touros e bodes, e as cinzas de uma novilha espalhadas sobre os imundos, santifica para a purificação do corpo,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 9, 14, 'quanto mais o sangue do Cristo que, pelo Espírito eterno, ofereceu a si mesmo, imaculado, a Deus, purificará a vossa consciência das obras mortas, para servirdes ao Deus vivo!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 9, 15, 'E por isso ele é o Mediador de um Novo Testamento, a fim de que, com a ocorrência de uma morte para redenção das transgressões sob o primeiro Testamento, os que foram chamados recebam a promessa da herança eterna.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 9, 16, 'Pois onde há um testamento, é necessário que ocorra a morte do testador;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 9, 17, 'porque um testamento se confirma nos mortos, visto que não é válido enquanto o testador vive.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 9, 18, 'Por isso o primeiro [testamento] também não foi consagrado sem sangue;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 9, 19, 'Porque, depois de Moisés haver pronunciado a todo o povo todo mandamento segundo a Lei, ele tomou o sangue de bezerros e de bodes, com água, lã purpúrea, e hissopo, e aspergiu, tanto o próprio livro, como todo o povo,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 9, 20, 'dizendo: Este é o sangue do pacto que Deus ordenou para vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 9, 21, 'E semelhantemente aspergiu com o sangue o Tabernáculo, e todos os utensílios do serviço de culto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 9, 22, 'Segundo a Lei, quase todas as coisas são purificadas com sangue, e sem derramamento de sangue não há perdão de pecados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 9, 23, 'Portanto era necessário que os esboços das coisas que estão nos céus fossem purificados com esses [sacrifícios] ; mas as próprias coisas celestiais, com sacrifícios melhores que esses.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 9, 24, 'Pois Cristo não entrou num santuário feito por mãos, mera figura do verdadeiro; mas sim, no próprio Céu, para agora comparecer por nós diante da face de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 9, 25, 'Também não [entrou] para oferecer a si mesmo muitas vezes, como o sumo sacerdote entra a cada ano no santuário com sangue alheio;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 9, 26, '(de outra maneira lhe seria necessário padecer muitas vezes desde a fundação do mundo), mas agora, no fim dos tempos, ele se manifestou de uma vez por todas para aniquilar o pecado pelo sacrifício de si mesmo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 9, 27, 'E, como está ordenado aos seres humanos morrerem uma vez, e depois disso, o juízo,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 9, 28, 'assim também Cristo, que se ofereceu uma vez para tirar os pecados de muitos, aparecerá pela segunda vez, sem pecado, aos que o esperam, para a salvação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 10, 1, 'Pois, como a Lei tem uma sombra dos bens futuros, e não a própria imagem das coisas, ela nunca pode, por meio dos mesmos sacrifícios que se oferecem a cada ano, continuamente, tornar perfeitos os que se aproximam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 10, 2, 'Caso contrário, deixariam de ser oferecidos, pois os adoradores, uma vez purificados, não teriam mais consciência alguma de pecados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 10, 3, 'Porém nesses [sacrifícios] a cada ano [se faz] uma nova lembrança dos pecados,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 10, 4, 'porque é impossível que o sangue de touros e de bodes tire pecados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 10, 5, 'Por isso que, quando ele entrou no mundo, disse: Sacrifício e oferta não quiseste, mas me preparaste um corpo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 10, 6, 'Ofertas de queima e ofertas pelo pecado não te agradaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 10, 7, 'Então eu disse: “Eis-me aqui; (no rolo do livro está escrito de mim) venho para fazer a tua vontade, ó Deus”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 10, 8, 'Depois de ter dito acima: “Sacrifício, oferta, holocaustos, e ofertas pelo pecado não quiseste, nem te agradaram”, (os quais se oferecem segundo a Lei),'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 10, 9, 'então disse: “Eis-me aqui, venho para fazer a tua vontade, ó Deus”. [Assim] , ele cancela o primeiro [pacto] ,para estabelecer o segundo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 10, 10, 'Pela sua vontade somos santificados por meio da oferta sacrificial do corpo de Jesus Cristo, [feita] de uma vez por todas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 10, 11, 'Todo sacerdote comparece a cada dia para servir e oferecer muitas vezes os mesmos sacrifícios, que nunca podem tirar os pecados;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 10, 12, 'Mas [Jesus] ,depois que ofereceu um sacrifício pelos pecados, assentou-se para sempre à direita de Deus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 10, 13, 'e espera desde então, até que os seus inimigos sejam postos por escabelo dos seus pés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 10, 14, 'Pois com uma só oferta ele aperfeiçoou para sempre os que são santificados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 10, 15, 'E também o Espírito Santo nos dá testemunho [acerca disso] ; pois, depois de haver anteriormente dito:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 10, 16, 'Este é o pacto que farei com eles depois daqueles dias, diz o Senhor: Porei minhas leis em seus corações, e as escreverei em suas mentes;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 10, 17, '[Então ele diz] : E não mais me lembrarei dos seus pecados e das suas transgressões.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 10, 18, 'Ora, onde há perdão dessas coisas, não há mais oferta pelo pecado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 10, 19, 'Portanto, irmãos, já que temos a confiança de entrar no Santuário pelo sangue de Jesus,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 10, 20, 'pelo caminho novo e vivo que ele consagrou para nós através do véu, isto é, pela sua carne;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 10, 21, 'e já que temos um grande Sacerdote sobre a casa de Deus,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 10, 22, 'aproximemo-nos com um coração sincero em plena certeza de fé, tendo os corações aspergidos e purificados da má consciência, e o corpo lavado com água pura;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 10, 23, 'mantenhamos firme a esperança que declararmos ter, sem abalo algum, pois aquele que prometeu é fiel;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 10, 24, 'e sejamos atenciosos uns para com os outros, a fim de incentivar o amor e as boas obras;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 10, 25, 'não abandonando a nossa reunião, como é o costume de alguns. Ao contrário, encorajemos [uns aos outros] , e tanto mais quanto vedes aquele dia se aproximando.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 10, 26, 'Pois se nós, depois de havermos recebido o conhecimento da verdade, persistirmos pecando por vontade própria, já não resta mais sacrifício pelos pecados;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 10, 27, 'em vez disso, certa terrível expectativa de julgamento, e um fogo de indignação que consumirá os adversários.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 10, 28, 'Se alguém que rejeita a Lei de Moisés morre sem misericórdia com base [na palavra de] duas ou três testemunhas,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 10, 29, 'de quanto pior castigo vós pensais que será julgado merecedor aquele que pisou o Filho de Deus, menosprezou ) o sangue do Testamento no qual ele foi santificado, e insultou o Espírito da graça?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 10, 30, 'Pois nós conhecemos aquele que disse: A vingança é minha; eu retribuirei, diz o Senhor. E outra vez: O Senhor julgará o seu povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 10, 31, 'Cair nas mãos do Deus vivo é algo terrível.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 10, 32, 'Lembrai-vos, porém, dos dias passados, em que, depois de serdes iluminados, suportastes grande combate de aflições,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 10, 33, 'quando, em parte, fostes expostos em público tanto a insultos, como a tribulações, e em parte, fostes companheiros daqueles que assim foram tratados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 10, 34, 'Pois também vos compadecestes das minhas prisões, e com alegria aceitastes a espoliação dos vossos bens, pois sabeis em vós mesmos que tendes nos Céus um bem melhor e permanente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 10, 35, 'Portanto, não rejeiteis a vossa confiança, que tem uma grande recompensa;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 10, 36, 'pois precisais de paciência, a fim de que, depois que houverdes feito a vontade de Deus, recebais o que foi prometido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 10, 37, 'Pois ainda um pouquinho de tempo, e aquele que vem virá, e não tardará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 10, 38, 'Mas o justo viverá pela fé; e se ele retroceder, a minha alma não tem prazer nele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 10, 39, 'Mas nós não somos dos que retrocedem para a perdição, mas sim dos que creem para a conservação da alma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 11, 1, 'Ora, a fé é a certeza das coisas que se esperam, e a prova das coisas que não se veem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 11, 2, 'Pois por ela os antigos obtiveram testemunho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 11, 3, 'Pela fé entendemos que o universo foi aprontado pela palavra de Deus, de maneira que as coisas que se veem não foram feitas de algo visível.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 11, 4, 'Pela fé, Abel ofereceu a Deus melhor sacrifício do que Caim; por isso obteve testemunho de que era justo, pois Deus testemunhou de suas ofertas; e mesmo estando morto, ainda fala por meio dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 11, 5, 'Pela fé, Enoque foi transportado para não experimentar a morte; e não foi achado, porque Deus havia o transportado; pois antes da sua transportação ele obteve testemunho de ter agradado a Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 11, 6, 'Ora, sem fé é impossível agradar [a Deus] . Pois é necessário que aquele que se aproxima de Deus creia que ele existe, e que ele é recompensador dos que o buscam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 11, 7, 'Pela fé, Noé, divinamente advertido das coisas que ainda se não viam, temeu; e, para salvamento de sua família construiu a arca. Por meio da fé ele condenou o mundo, e foi feito herdeiro da justiça segundo a fé.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 11, 8, 'Pela fé, Abraão, quando foi chamado para ir ao lugar que havia de receber por herança, obedeceu, e saiu sem que soubesse aonde ia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 11, 9, 'Pela fé, ele habitou na terra de promessa, como em [terra] que não fosse sua, morando em tendas com Isaque e com Jacó, herdeiros com ele da mesma promessa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 11, 10, 'Pois ele esperava a cidade que tem fundamentos firmes, da qual o arquiteto e construtor é Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 11, 11, 'Pela fé, também, a própria Sara recebeu a capacidade de conceber descendência, e já na idade avançada ela deu à luz, pois considerou fiel aquele que havia prometido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 11, 12, 'Assim, de um que estava à beira da morte, nasceu [uma descendência] numerosa como as estrelas do céu, e incontável como a areia na praia do mar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 11, 13, '[Permanecendo] na fé, todos esses morreram sem receberem as promessas. Mas as viram de longe, creram, e felicitaram-se nelas, declarando que eram estrangeiros e peregrinos na terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 11, 14, 'Pois os que dizem tais coisas mostram claramente que estão buscando a [sua] própria pátria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 11, 15, 'Ora, se estivessem pensando naquela de onde saíram, eles tinham oportunidade de voltar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 11, 16, 'Mas agora desejam uma melhor, isto é, a celestial. Por isso Deus não se envergonha deles, de ser chamado o Deus deles, porque já lhes preparou uma cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 11, 17, 'Pela fé, Abraão, quando foi provado, ofereceu Isaque; aquele que havia recebido as promessas ofereceu o [seu] único filho,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 11, 18, 'do qual foi dito: Em Isaque será chamada a tua descendência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 11, 19, '[Abraão] considerou que Deus era poderoso até para ressuscitar [Isaque] dos mortos; de onde também, de forma figurada, ele o recuperou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 11, 20, 'Pela fé, Isaque abençoou Jacó e Esaú quanto às coisas futuras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 11, 21, 'Pela fé, Jacó, enquanto morria, abençoou a cada um dos filhos de José, e adorou [apoiado] sobre a ponta do seu cajado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 11, 22, 'Pela fé, José, no fim de sua vida, mencionou a saída dos filhos de Israel, e deu ordem acerca dos seus ossos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 11, 23, 'Pela fé, Moisés, quando nasceu, foi escondido três meses pelos seus pais, pois viram que o menino era belo, e não se intimidaram com o mandamento do rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 11, 24, 'Pela fé, Moisés, sendo já crescido, recusou ser chamado filho da filha de faraó;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 11, 25, 'pois preferiu ser maltratado com o povo de Deus a ter por um tempo o prazer do pecado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 11, 26, 'Ele considerou que as humilhações por causa de Cristo eram riquezas maiores que os tesouros no Egito; pois sua atenção estava fixada na recompensa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 11, 27, 'Pela fé, ele deixou o Egito sem temer a ira do rei, pois perseverou como que vendo aquele que é invisível.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 11, 28, 'Pela fé, ele celebrou a Páscoa e o derramamento do sangue, para que o destruidor dos primogênitos não os tocasse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 11, 29, 'Pela fé, atravessaram o mar Vermelho, como que por [ terra ] seca, o que, quando os Egípcios tentaram, afogaram-se.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 11, 30, 'Pela fé, os muros de Jericó caíram, depois de serem rodeados por sete dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 11, 31, 'Pela fé, Raabe, a prostituta, não pereceu com os incrédulos, pois acolheu em paz os espias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 11, 32, 'E que mais direi? Pois me faltará tempo se eu contar a respeito de Gideão, Baraque, e também de Sansão, Jefté, Davi, e também de Samuel e dos profetas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 11, 33, 'Pela fé, esses venceram reinos, exercitaram justiça, alcançaram promessas, fecharam bocas de leões,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 11, 34, 'apagaram o poder do fogo, escaparam do fio de espada, da fraqueza tiraram forças, tonaram-se fortes na batalha, puseram em fuga os exércitos dos estrangeiros;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 11, 35, 'As mulheres receberam de volta os seus mortos pela ressurreição; e outros foram torturados, não aceitando a soltura, para alcançarem uma melhor ressurreição;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 11, 36, 'e outros experimentaram provação de insultos e açoites, e até correntes e prisões;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 11, 37, 'foram apedrejados, serrados, tentados, morreram pela espada; andaram [vestidos] de peles de ovelhas e de cabras; necessitados, afligidos, maltratados;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 11, 38, '(o mundo não era digno deles) andando sem rumo em desertos, montanhas, covas, e nas cavernas da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 11, 39, 'E todos esses, [mesmo] tendo testemunho pela fé, não alcançaram a promessa,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 11, 40, 'pois Deus havia preparado algo melhor para nós, para que, sem nós, eles não fossem aperfeiçoados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 12, 1, 'Portanto nós também, posto que estamos rodeados por uma tão grande nuvem de testemunhas, deixemos toda sobrecarga, e o pecado que facilmente nos envolve, e corramos com perseverança a corrida que nos está proposta,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 12, 2, 'olhando para Jesus, Autor e aperfeiçoador da fé. Ele, pela alegria que lhe estava proposta, suportou a cruz, desprezando a humilhação, e assentou-se à direita do trono de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 12, 3, 'Considerai, pois, aquele que suportou tal hostilidade dos pecadores contra si mesmo, para que não fiqueis exaustos, nem vossas almas se debilitem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 12, 4, 'Enquanto lutais contra o pecado, ainda não resististes ao ponto de ter o próprio sangue derramado,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 12, 5, 'mas já vos esquecestes do encorajamento que ele fala convosco como a filhos: Meu filho, não desprezes a disciplina do Senhor, nem te canses de ser reprendido por ele;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 12, 6, 'pois o Senhor disciplina a quem ama, e açoita a todo filho a quem recebe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 12, 7, 'Se suportais a disciplina, Deus vos trata como filhos; pois que filho há a quem o pai não discipline?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 12, 8, 'Mas se estais sem disciplina, da qual todos são feitos participantes, então sois ilegítimos, e não filhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 12, 9, 'Além disso, tivemos os pais de nossa carne como disciplinadores, e nós os respeitávamos. Por acaso não nos sujeitaremos muito mais ao Pai dos espíritos, a fim de vivermos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 12, 10, 'Porque eles, por um pouco de tempo, [nos] disciplinavam como bem lhes parecia. Ele, porém, [disciplina] para o [nosso] proveito, a fim de que sejamos participantes da sua santidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 12, 11, 'De fato, no presente, nenhuma disciplina parece ser motivo de alegria, mas sim, de sofrimento; mas depois produz um fruto pacífico de justiça aos que foram exercitados por ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 12, 12, 'Portanto, levantai as mãos cansadas e os joelhos enfraquecidos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 12, 13, 'e “fazei caminhos retos para os vossos pés”, para que o que está manco não se desvie, em vez disso, seja sarado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 12, 14, 'Buscai a paz com todos, e a santificação, sem a qual ninguém verá o Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 12, 15, 'Vigiai com empenho para que ninguém perca de receber da graça de Deus; para não acontecer que alguma raiz de amargura brote, seja incômoda, e muitos sejam contaminados por ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 12, 16, 'Ninguém seja pecador sexual, ou profano como Esaú, que por uma refeição vendeu o seu direito de primogenitura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 12, 17, 'Pois vós sabeis que depois, quando ele quis herdar a benção, foi rejeitado, porque não achou lugar para arrependimento, ainda que com lágrimas o tenha buscado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 12, 18, 'Porque não chegastes a um monte palpável, aceso com fogo, e à escuridão, às trevas, e à tempestade;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 12, 19, 'ao som da trombeta, e à voz das palavras, que os que a ouviam, rogaram que não mais se lhes falasse palavra alguma;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 12, 20, '(pois não podiam suportar o que [lhes] era ordenado: Se até um animal tocar o monte, seja apedrejado ou perfurado com um dardo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 12, 21, 'E a visão era tão terrível, que Moisés disse: Estou assombrado e tremendo).'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 12, 22, 'Mas vós chegastes ao monte Sião, à cidade do Deus vivo, a Jerusalém celestial, e aos muitos milhares de anjos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 12, 23, 'à universal congregação e igreja dos primogênitos inscritos nos Céus, e a Deus, o Juiz de todos, e aos espíritos dos justos já aperfeiçoados;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 12, 24, 'e a Jesus, o Mediador de um Novo Testamento, e ao sangue da aspersão, que fala melhores coisas que [o de] Abel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 12, 25, 'Tende o cuidado de não rejeitardes ao que fala. Pois, se não escaparam aqueles que rejeitaram ao que [os] advertia divinamente na terra, muito menos nós, se nos desviarmos daquele que [nos adverte] dos Céus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 12, 26, 'Sua voz fez a terra tremer naquela ocasião, mas agora ele prometeu, dizendo: Ainda uma vez faço tremer não somente a terra, mas também o Céu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 12, 27, 'Esta [expressão] , “Ainda uma vez”, mostra a remoção das coisas abaladas, como coisas criadas, para que as inabaláveis permaneçam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 12, 28, 'Por isso, já que recebemos um Reino inabalável, mantenhamos a graça, e por ela sirvamos a Deus de maneira que o agrade, com devoção e temor,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 12, 29, 'pois o nosso Deus é um fogo consumidor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 13, 1, 'Permaneça o amor fraternal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 13, 2, 'Não vos esqueçais de mostrar hospitalidade, porque através dela alguns, sem saber, acolheram anjos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 13, 3, 'Lembrai-vos dos prisoneiros, como se estivésseis presos com eles; e dos que são maltratados, como se vós mesmos também estivessem sendo em [vossos] corpos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 13, 4, 'O matrimônio seja honrado entre todos, e o leito conjugal sem contaminação; mas Deus julgará os pecadores sexuais e os adúlteros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 13, 5, 'A [vossa] maneira de viver seja sem ganância, contentando-vos com as coisas que tendes. Pois ele disse: Não te deixarei, nem te desampararei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 13, 6, 'De maneira que devemos ter a confiança de dizer: O Senhor é meu ajudador; não temerei o que o ser humano poderá fazer a mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 13, 7, 'Lembrai-vos de vossos líderes, que vos falaram a palavra de Deus. Observai o resultado da maneira como viveram, e imitai a fé deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 13, 8, 'Jesus Cristo é o mesmo ontem, hoje, e eternamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 13, 9, 'Não vos deixeis levar por doutrinas várias e estranhas. Pois bom ao coração é ser fortificado pela graça, e não por alimentos, que não resultaram em proveito algum aos que com eles se ocuparam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 13, 10, 'Temos um altar, do qual os que servem no tabernáculo não têm autoridade para comer;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 13, 11, 'porque os corpos dos animais, cujo sangue pelo pecado é trazido ao Santuário pelo Sumo sacerdote, são queimados fora do acampamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 13, 12, 'Por isso também Jesus, para santificar o povo pelo seu próprio sangue, sofreu fora do portão da cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 13, 13, 'Assim, saiamos até ele, fora do acampamento, carregando a sua humilhação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 13, 14, 'Pois não temos aqui cidade permanente, mas buscamos a futura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 13, 15, 'Portanto, por meio dele, ofereçamos continuamente sacrifício de louvor a Deus, isto é, o fruto dos lábios que declaram honra ao seu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 13, 16, 'E não vos esqueçais de fazer o bem e de compartilhar, pois Deus se agrada com tais sacrifícios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 13, 17, 'Obedecei aos vossos líderes, e sede submissos [a eles] ,pois eles vigiam pelas vossas almas, como os que prestarão contas [delas] ; para que o façam com alegria, e não gemendo, porque isso não vos seria proveitoso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 13, 18, 'Orai por nós; porque confiamos que temos boa consciência, e desejamos nos comportar da maneira correta em tudo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 13, 19, 'E eu vos rogo ainda mais que façais isto, para que eu vos seja restituído mais depressa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 13, 20, 'O Deus da paz, que, pelo sangue do eterno Testamento eterno, voltou a trazer dentre os mortos o grande Pastor das ovelhas, o nosso Senhor Jesus,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 13, 21, 'vos aperfeiçoe em toda boa obra, para fazerdes a sua vontade, operando em vós o que é agradável diante dele, por meio de Jesus Cristo, a quem seja a glória para todo o sempre. Amém!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 13, 22, 'Eu vos rogo, porém, irmãos, que suportai esta palavra de exortação; pois eu vos escrevi de maneira breve.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 13, 23, 'Sabei que o irmão Timóteo já está solto. Se ele vier depressa, com ele eu vos verei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 13, 24, 'Saudai a todos os vossos líderes, e a todos os santos. Os da Itália vos saúdam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 13, 25, 'A graça seja com todos vós. Amém.[Escrita da Itália para os Hebreus, e enviada por Timóteo]'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 1, 1, 'Tiago, servo de Deus e do Senhor Jesus Cristo, às doze tribos que [estão] na dispersão, saudações!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 1, 2, 'Meus irmãos, tende toda alegria quando vos encontrardes em várias provações,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 1, 3, 'sabendo que a prova da vossa fé produz perseverança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 1, 4, 'E que a perseverança tenha uma realização completa, para que sejais completos e íntegros, faltando em nada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 1, 5, 'Se algum de vós tem falta de sabedoria, peça a Deus, que concede generosamente a todos sem repreender, e lhe será dada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 1, 6, 'Porém deves pedi-la em fé, duvidando em nada; pois quem duvida é semelhante à onda do mar que é levada pelo vento, e lançada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 1, 7, 'Tal pessoa não pense que receberá algo do Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 1, 8, 'O homem de dupla mentalidade [é] inconstante em todos os seus caminhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 1, 9, 'Mas o irmão que é humilde se orgulhe quando é exaltado,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 1, 10, 'e o que é rico quando é abatido, porque ele passará como a flor da erva.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 1, 11, 'Pois o sol sai com ardor, então seca a erva, a sua flor cai, e a beleza do seu aspecto perece; assim também o rico murchará nos seus caminhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 1, 12, 'Bendito é o homem que suporta a provação; pois, quando for aprovado, receberá a coroa da vida, que o Senhor prometeu aos que o amam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 1, 13, 'Ninguém, quando for tentado, diga: “Sou tentado por Deus”; porque Deus não é tentado pelo mal, e ele mesmo tenta ninguém;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 1, 14, 'Mas cada um é tentado quando é atraído e seduzido pelo seu próprio mau desejo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 1, 15, 'Depois do mau desejo ter concebido, dá à luz o pecado; e o pecado, quando é completado, gera a morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 1, 16, 'Não vos enganeis, meus amados irmãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 1, 17, 'Toda boa dádiva e todo dom perfeito vem do alto, e desce do Pai das luzes, em quem não há mudança nem sombra de variação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 1, 18, 'Conforme a sua própria vontade, ele nos gerou pela palavra da verdade, para que fôssemos os primeiros frutos dentre as suas criaturas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 1, 19, 'Portanto, meus amados irmãos, toda pessoa seja pronta para ouvir, tardia para falar, tardia para se irar;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 1, 20, 'porque a ira humana não cumpre a justiça de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 1, 21, 'Por isso, rejeitai toda impureza e abundância de malícia, e recebei com mansidão a palavra implantada em [vós] , que pode salvar as vossas almas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 1, 22, 'e sede praticantes da palavra, e não somente ouvintes, enganando a vós mesmos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 1, 23, 'Pois, se alguém é ouvinte da palavra e não praticante, esse é semelhante a um homem que observa num espelho o seu rosto natural;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 1, 24, 'porque observou a si mesmo e saiu, e logo se esqueceu de como era.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 1, 25, 'Mas aquele que dá atenção à lei perfeita, a da liberdade, e [nela] persevera, não sendo ouvinte que esquece, mas sim praticante da obra, esse tal será bendito no que fizer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 1, 26, 'Se alguém entre vós pensa ser religioso, mas não controla a sua língua, então engana o seu próprio coração, e a religião desse é vã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 1, 27, 'A religião pura e não contaminada para com Deus e Pai é esta: visitar os órfãos e as viúvas nas suas aflições, e guardar-se sem a corrupção do mundo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 2, 1, 'Meus irmãos, não tenhais a fé do nosso glorioso Senhor Jesus Cristo em acepção de pessoas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 2, 2, 'Pois se algum homem entrar na vossa congregação com anéis de ouro e trajes preciosos, e também entrar algum pobre com roupa de pouco valor,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 2, 3, 'e derdes atenção ao que usa o traje precioso, e lhe disserdes: “Senta aqui, num lugar de honra”, mas ao pobre disserdes: “Fica ali em pé” ou “senta-te aqui abaixo do apoio dos meus pés”,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 2, 4, 'por acaso não fizestes discriminação entre vós mesmos, e não vos tornastes juízes de maus pensamentos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 2, 5, 'Ouvi, meus amados irmãos: acaso Deus não escolheu os pobres deste mundo para [serem] ricos na fé, e herdeiros do reino que ele prometeu aos que o amam?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 2, 6, 'Vós, porém, desonrastes o pobre. Acaso não são os ricos que vos oprimem e vos arrastam para os tribunais?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 2, 7, 'Não são eles que blasfemam o bom nome pelo qual sois chamados?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 2, 8, 'Se de fato cumpris a lei real conforme a Escritura: Amarás o teu próximo como a ti mesmo, bem fazeis;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 2, 9, 'Mas se fazeis acepção de pessoas, cometeis pecado, e sois denunciados pela lei como transgressores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 2, 10, 'Pois quem guarda toda a lei, mas falha em um [item] , tornou-se culpado de todos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 2, 11, 'Porque aquele que disse: “Não cometerás adultério”, também disse: “Não matarás”. Portanto, se não cometeres adultério, mas matares, te tornaste um transgressor da lei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 2, 12, 'Falai assim e procedei assim: como os que serão julgados pela lei da liberdade;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 2, 13, 'porque o julgamento [será] sem misericórdia sobre quem não agiu com misericórdia; mas a misericórdia triunfa sobre o julgamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 2, 14, 'Meus irmãos, qual é o proveito se alguém disser que tem fé, mas não tiver obras? Acaso a fé pode salvá-lo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 2, 15, 'E se um irmão ou irmã estiverem nus, e necessitarem do alimento diário,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 2, 16, 'e algum de vós lhes disser: “Ide em paz, aquecei-vos e saciai-vos”; e não lhes derdes as coisas necessárias ao corpo, qual é o proveito [disso] ?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 2, 17, 'Assim também a fé, se não tiver obras, é morta em si mesma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 2, 18, 'Mas alguém dirá: Tu tens fé e eu tenho obras. Mostra-me a tua fé pelas tuas obras, e eu, pelas minhas obras, te mostrarei a minha fé.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 2, 19, 'Tu crês que há um só Deus? Fazes bem; os demônios também creem, e estremecem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 2, 20, 'Ó tolo, queres te certificar de que a fé sem as obras é morta?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 2, 21, 'Acaso não foi o nosso pai Abraão justificado pelas obras, quando ofereceu o seu filho Isaque sobre o altar?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 2, 22, 'Vês que a fé cooperou com as suas obras, e que pelas obras a fé foi aperfeiçoada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 2, 23, 'E cumpriu-se a Escritura que diz: “E Abraão creu em Deus, e isso lhe foi considerado como justiça”, e ele foi chamado amigo de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 2, 24, 'Vedes, então, que o ser humano é justificado pelas obras, e não somente pela fé.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 2, 25, 'E de igual modo não foi também a prostituta Raabe justificada pelas obras, quando recebeu os mensageiros, e ajudou para que saíssem por outro caminho?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 2, 26, 'Pois assim como o corpo sem o espírito está morto, assim também a fé sem obras está morta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 3, 1, 'Meus irmãos, não sejais muitos de vós mestres, porque sabeis que receberemos um julgamento mais rigoroso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 3, 2, 'Pois todos tropeçamos em muitas coisas. Se alguém não tropeça no que diz, tal homem é completo, e também capaz de refrear todo o corpo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 3, 3, 'Eis que pomos freios nas bocas dos cavalos para nos obedecerem, e [assim] manobramos todo o corpo deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 3, 4, 'Vede também os navios, sendo tão grandes, e levados por impetuosos ventos, são manobrados com um pequeníssimo leme para onde quer que queira o impulso daquele que dirige.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 3, 5, 'Assim também a língua é um pequeno membro, mas se orgulha de grandes coisas. Vede como um pequeno fogo incendeia um grande bosque!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 3, 6, 'A língua também [é] um fogo, o mundo da injustiça; assim a língua está posta entre os nossos membros, contaminando o corpo todo, inflamando o curso da natureza humana, e sendo inflamada pelo inferno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 3, 7, 'Pois toda espécie, tanto de animais selvagens como de aves, tanto de répteis como de animais marinhos, é dominível e tem sido dominada pela espécie humana;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 3, 8, 'Mas nenhum ser humano consegue dominar a língua; ela é um mal difícil de se controlar, cheia de veneno mortal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 3, 9, 'Com ela bendizemos o Deus e Pai, e com ela amaldiçoamos os seres humanos, que são feitos à semelhança de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 3, 10, 'Da mesma boca procedem benção e maldição. Meus irmãos, isso não deve ser assim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 3, 11, 'Acaso uma fonte jorra do mesmo manancial [água] doce e [água] amarga?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 3, 12, 'Meus irmãos, pode a figueira dar azeitonas, ou a videira figos? Assim [também] , nenhuma fonte dá tanto água salgada como doce.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 3, 13, 'Quem dentre vós for sábio e inteligente, que mostre pela boa conduta as suas obras em humildade de sabedoria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 3, 14, 'Porém, se tendes amarga inveja e rivalidade no vosso coração, não vos orgulheis, nem mintais contra a verdade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 3, 15, 'Esta sabedoria não é a que vem do alto, mas sim, terrena, animal, [e] demoníaca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 3, 16, 'Pois onde [há] inveja e rivalidade, ali [há] perturbação e toda obra perversa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 3, 17, 'Mas a sabedoria do alto é primeiramente pura, depois pacífica, moderada, tratável, cheia de misericórdia e de bons frutos, imparcial e sem hipocrisia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 3, 18, 'E o fruto da justiça é semeado na paz para os que praticam a paz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 4, 1, 'De onde [vêm] as guerras e brigas entre vós? Acaso não [vêm] disto, das vossas cobiças que guerreiam nos membros do vosso corpo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 4, 2, 'Cobiçais, e nada tendes; matais e sois invejosos, mas não conseguis obter; combateis e guerreais, mas nada tendes, porque não pedis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 4, 3, 'Pedis, e não recebeis, porque pedis mal, para gastardes nos vossos prazeres.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 4, 4, 'Adúlteros e adúlteras, não sabeis que a amizade do mundo é inimizade contra Deus? Portanto, quem quiser ser amigo do mundo constitui-se inimigo de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 4, 5, 'Ou pensais ser em vão que a Escritura diz: “O Espírito que habita em nós ansia com ciúmes?”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 4, 6, 'Porém ele concede uma graça maior. Por isso diz: Deus resiste aos soberbos, mas concede graça aos humildes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 4, 7, 'Sujeitai-vos, pois, a Deus; resisti ao diabo, e ele fugirá de vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 4, 8, 'Aproximai-vos de Deus, e ele se aproximará de vós. Limpai as [vossas] mãos, pecadores, e vós de dupla mentalidade, purificai os [vossos] corações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 4, 9, 'Reconhecei vossas misérias, lamentai e chorai. Torne-se o vosso riso em pranto, e a [vossa] alegria em tristeza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 4, 10, 'Humilhai-vos diante do Senhor, e ele vos exaltará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 4, 11, 'Irmãos, não faleis mal uns dos outros. Quem fala mal de um irmão, e julga o seu irmão, fala mal da lei, e julga a lei. E se julgas a lei, não és um cumpridor da lei, mas, sim, juiz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 4, 12, 'Um [só] é o Legislador, que pode salvar e destruir. Quem és tu, que julgas o outro?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 4, 13, 'Atenção! Vós que dizeis: “Hoje ou amanhã iremos a uma tal cidade, e lá passaremos um ano negociando e lucrando”;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 4, 14, 'mas não sabeis o amanhã. Pois o que [é] a vossa vida? É um vapor, que por pouco tempo aparece, e logo se desvanece.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 4, 15, 'Em vez disso, devíeis dizer: Se o Senhor quiser, e vivermos, faremos isso ou aquilo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 4, 16, 'Mas agora vos orgulhais nas vossas presunções; todo orgulho como esse é maligno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 4, 17, 'Portanto, quem sabe fazer o bem, e não [o] faz, comete pecado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 5, 1, 'Cuidado, ricos! Chorai e gemei pelas vossas misérias que virão sobre [vós] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 5, 2, 'As vossas riquezas estão podres, e as vossas roupas estão comidas pela traça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 5, 3, 'O vosso ouro e a vossa prata estão enferrujados, e a ferrugem deles será testemunho contra vós, e comerá a vossa carne como fogo. Acumulastes tesouro para os dias finais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 5, 4, 'Eis que o salário dos trabalhadores que colheram nos vossos campos, que por vós foi retido fraudulentamente, está clamando; e os clamores dos que fizeram a colheita chegaram os ouvidos do Senhor dos exércitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 5, 5, 'Vivestes em luxo sobre a terra, e tivestes prazeres. Engordastes os vossos corações como num dia de matança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 5, 6, 'Condenastes [e] matastes o justo; ele não vos resistiu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 5, 7, 'Portanto, irmãos, sede pacientes até a vinda do Senhor. Eis que o lavrador espera o precioso fruto da terra, aguardando-o com paciência, até que receba a primeira chuva e a chuva tardia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 5, 8, 'Sede vós também pacientes. Fortalecei os vossos corações, porque a vinda do Senhor está próxima.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 5, 9, 'Irmãos, não vos queixeis uns contra os outros, para que não sejais condenados. Eis que o Juiz está à porta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 5, 10, 'Meus irmãos, tomai como exemplo de aflições e de paciência os profetas que falaram no nome do Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 5, 11, 'Eis que considerarmos benditos os que suportam o sofrimento. Ouvistes da paciência de Jó, e vistes o resultado da parte do Senhor; porque o Senhor é muito misericordioso, e cheio de compaixão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 5, 12, 'Mas, acima de tudo, meus irmãos, não jureis, nem pelo céu nem pela terra, nem [façais] qualquer outro juramento. Mas que de vós o sim seja sim, e o não, não; para que não caiais em condenação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 5, 13, 'Alguém entre vós está aflito? Ore. Alguém está contente? Cante louvores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 5, 14, 'Alguém entre vós está doente? Chame os anciãos da igreja, e orem sobre ele, ungindo-o com azeite no nome do Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 5, 15, 'E a oração da fé sarará o doente, e o Senhor o levantará; e se houver cometido pecados, lhe serão perdoados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 5, 16, 'Confessai as [vossas] culpas uns aos outros, e orai uns pelos outros, para que sejais curados. A oração de um justo muito pode efetuar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 5, 17, 'Elias era tão humano quanto nós, e orou insistentemente para não chover; e não choveu sobre a terra por três anos e seis meses.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 5, 18, 'E orou outra vez, e o céu deu chuva, e a terra produziu o seu fruto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 5, 19, 'Irmãos, se algum entre vós houver se desviado da verdade, e alguém o converter,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 59, 'Tiago', 'Tg', 5, 20, 'saiba que aquele que converter um pecador do erro de seu caminho, salvará uma alma da morte, e cobrirá uma multidão de pecados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 1, 1, 'Pedro, apóstolo de Jesus Cristo, aos forasteiros que estão espalhados em Ponto, Galácia, Capadócia, Ásia e Bitínia,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 1, 2, 'escolhidos segundo o pré-conhecimento de Deus Pai, por meio da santificação do Espírito, para a obediência e a aspersão do sangue de Jesus Cristo. Que a graça e a paz vos sejam multiplicadas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 1, 3, 'Bendito seja o Deus e Pai de nosso Senhor Jesus Cristo. Segundo sua grande misericórdia, ele nos regenerou para uma esperança viva, por meio da ressurreição de Jesus Cristo dentre os mortos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 1, 4, 'E o resultado disso é uma herança incorruptível, incontaminável, e que não pode ser enfraquecida. Ela está guardada nos céus para vós,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 1, 5, 'que pela fé estais guardados no poder de Deus para a salvação, pronta para se revelar no último tempo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 1, 6, 'Nisso vos alegrais, ainda que agora seja necessário que estejais por um pouco [de tempo] entristecidos com várias provações,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 1, 7, 'para que a prova de vossa fé, muito mais preciosa que o ouro que perece (mesmo sendo provado pelo fogo), seja achada em louvor, honra, e glória, na revelação de Jesus Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 1, 8, 'A ele, sem terdes visto, vós o amais. Ainda que não estejais o vendo agora, mas crendo nele, vós estais alegres com júbilo indescritível e glorioso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 1, 9, 'Assim estais alcançando o resultado da vossa fé: a salvação das [vossas] almas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 1, 10, 'Dessa salvação os profetas que profetizaram a respeito da graça [direcionada] a vós procuraram entender, e com empenho investigaram,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 1, 11, 'procurando saber qual era o tempo ou ocasião que o Espírito de Cristo dentro deles indicava, quando dava prévio testemunho dos sofrimentos de Cristo e das glórias seguintes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 1, 12, 'A eles foi revelado que não foi para eles mesmos, mas sim para nós, que eles prestaram serviço com estas coisas. E agora, elas vos foram anunciadas pelos que, pelo Espírito Santo enviado do céu, vos pregaram o Evangelho. Tais coisas os anjos desejam atentamente observar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 1, 13, 'Portanto, preparai as vossas mentes, sede sóbrios, e esperai completamente na graça que vos será trazida na revelação de Jesus Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 1, 14, 'E, como filhos obedientes, não vos conformeis com os maus desejos do passado, de quando éreis ignorantes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 1, 15, 'Ao contrário; assim como aquele que vos chamou é santo, sede vós também santos em todo o [vosso] comportamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 1, 16, 'Pois está escrito: Sede santos, porque eu sou santo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 1, 17, 'E, se vós chamais de Pai aquele que, sem acepção de pessoas, julga segundo a obra de cada um, vivei em temor o tempo de vossa peregrinação;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 1, 18, 'e sabei que não foi por coisas destrutíveis, [como] prata ou ouro, que fostes resgatados da vossa vã maneira de viver que recebestes dos [vossos] pais,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 1, 19, 'mas sim, pelo sangue precioso, como de um cordeiro sem falha e sem contaminação: o [sangue] de Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 1, 20, 'Ele já era conhecido desde antes da fundação do mundo, mas foi manifesto nestes últimos tempos por causa de vós,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 1, 21, 'que, por meio dele, credes em Deus, que o ressuscitou dos mortos e lhe deu glória, para que a vossa fé e esperança estejam em Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 1, 22, 'Uma vez que purificastes as vossas almas na obediência da verdade por meio do Espírito, para o sincero amor fraternal, amai-vos intensamente uns aos outros com um coração puro,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 1, 23, 'visto que nascestes de novo, não de semente que perece, mas sim imperecível, pela viva palavra de Deus, que permanece para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 1, 24, 'Pois toda carne é como a erva, e toda glória humana como a flor da erva. A erva se seca, e sua flor cai;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 1, 25, 'mas a palavra do Senhor permanece para sempre.E esta é a palavra que foi evangelizada entre vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 2, 1, 'Abandonai, portanto, toda malícia, toda enganação, fingimentos, invejas, e todas as falas maldosas,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 2, 2, 'e desejai ansiosamente, como bebês recém-nascidos, o leite da Palavra, não falsificado, para que por meio dele estejais crescendo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 2, 3, 'se, de fato, já experimentastes que o Senhor é bom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 2, 4, 'Aproximai-vos dele, [que é] uma pedra viva, rejeitada pelos seres humanos, mas escolhida e preciosa para Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 2, 5, 'Também vós, como pedras vivas, sois edificados como casa espiritual [e] sacerdócio santo, para oferecerdes sacrifícios espirituais, agradáveis a Deus por meio de Jesus Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 2, 6, 'Por isso também está contido na Escritura: Eis que eu ponho em Sião uma pedra principal de esquina, escolhida [e] preciosa. Quem nela crer de maneira nenhuma será envergonhado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 2, 7, 'Assim, para vós, que credes, ela é preciosa. Mas para os rebeldes: A pedra que os construtores rejeitaram, essa se tornou a principal de esquina,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 2, 8, 'assim como pedra de tropeço, e pedra que causa queda. Eles tropeçam na palavra por serem rebeldes. Para isso eles foram destinados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 2, 9, 'Mas vós sois a geração escolhida, o sacerdócio real, a nação santa, o povo adquirido; a fim de que anuncieis as virtudes daquele que vos chamou das trevas para a sua maravilhosa luz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 2, 10, 'Antes, vós não éreis povo, mas agora sois povo de Deus. [Antes] , não havíeis recebido misericórdia, mas agora recebestes misericórdia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 2, 11, 'Amados, como a peregrinos e estrangeiros, eu vos peço que vos abstenhais dos desejos carnais, que batalham contra a alma,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 2, 12, 'e que tenhais um bom comportamento vosso entre os pagãos; para que, naquilo que de vós, como de malfeitores, falam mal, no dia da visitação glorifiquem a Deus por causa das [vossas] boas obras que tiverem visto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 2, 13, 'Portanto sujeitai-vos a toda autoridade humana, por causa do Senhor; seja ao rei, como superior;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 2, 14, 'seja aos governantes, como enviados por ele, com o objetivo de castigar os malfeitores, e de conceder honra aos que fazem o bem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 2, 15, 'Pois esta é a vontade de Deus, que, ao fazerdes o bem, caleis a ignorância dos homens tolos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 2, 16, '[Comportai-vos] como pessoas livres, mas não useis a liberdade como pretexto para a malícia. Em vez disso, [sede] como servos de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 2, 17, 'Honrai a todos: amai aos irmãos, temei a Deus, honrai ao rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 2, 18, 'Servos, sujeitai-vos com todo temor aos [vossos] senhores, não somente aos bons e brandos, mas também aos que maltratam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 2, 19, 'Pois coisa agradável é se alguém, por causa da consciência a respeito de Deus, experimente dores, sofrendo injustamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 2, 20, 'Afinal, que mérito há em suportar serdes espancados por cometerdes pecado? Contudo, se, quando fazeis o bem, sois afligidos e suportais, isso é a Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 2, 21, 'Pois para isto fostes chamados, porque também Cristo sofreu por nós, deixando-nos exemplo, para que sigais os seus passos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 2, 22, 'Ele não cometeu pecado, nem engano foi achado em sua boca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 2, 23, 'Quando o insultavam, ele não insultava de volta. Quando sofria, ele não ameaçava; em vez disso, entregava-se ao que julga de maneira justa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 2, 24, 'Ele levou nossos pecados em seu próprio corpo sobre o madeiro; para que nós, estando mortos para os pecados, vivamos para a justiça. Pela ferida dele fostes sarados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 2, 25, 'Porque vós éreis como ovelhas desviadas do caminho; mas agora vós estais convertidos ao Pastor e Supervisor de vossas almas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 3, 1, 'Semelhantemente vós, esposas, estejais sujeitas aos próprios maridos, para que, ainda que alguns não obedeçam à Palavra, por meio do comportamento das esposas, sem palavra, sejam ganhos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 3, 2, 'quando eles observarem o vosso comportamento puro e com temor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 3, 3, 'A vossa beleza não seja a exterior, [como] tranças de cabelos, joias de ouro, ou vestuário,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 3, 4, 'mas sim, a pessoa interior no coração, o [embelezamento] incorruptível de um espírito manso e tranquilo, que é precioso diante de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 3, 5, 'Pois assim também se embelezavam antigamente as mulheres santas, que esperavam em Deus, e eram sujeitas aos seus maridos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 3, 6, 'Dessa maneira Sara obedecia a Abraão, chamando-lhe de senhor. Vós sois filhas dela se fizerdes o bem e não temerdes espanto algum.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 3, 7, 'Semelhantemente vós maridos, convivei [com elas] com entendimento, dando honra à mulher, como a vaso mais fraco, como sendo [elas e vós] juntamente herdeiros da graça da vida; a fim de que as vossas orações não sejam impedidas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 3, 8, 'E por fim, sede todos de uma mesma mentalidade, compassivos, tenhais amor pelos irmãos, e sede misericordiosos e benevolentes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 3, 9, 'Não retribuais o mal com mal, ou insulto com insulto; ao contrário, bendizei, sabendo que para isto fostes chamados, para que herdeis a bênção.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 3, 10, 'Pois: quem quer amar a vida e ver dias bons, refreie sua língua do mal, e que seus lábios não falem engano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 3, 11, 'Afaste-se do mal, e faça o bem; busque a paz, e siga-a.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 3, 12, 'Porque os olhos do Senhor estão sobre os justos, e seus ouvidos [atentos] às suas orações; mas a face do Senhor é contra os que fazem o mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 3, 13, 'E quem vos fará mal se fordes adeptos do bem?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 3, 14, 'Porém, mesmo se sofrerdes por causa da justiça, benditos sois. Não tenhais medo deles, nem vos perturbeis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 3, 15, 'Mas santificai a Deus como Senhor em vossos corações; e estai sempre preparados para responder com mansidão e respeito a todo aquele que vos pedir a razão da esperança que há em vós,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 3, 16, 'tendo uma boa consciência; para que, naquilo que falam mal de vós como malfeitores, os que insultam o vosso bom comportamento em Cristo sejam envergonhados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 3, 17, 'Pois é melhor que sofrais fazendo o bem, se [assim] a vontade de Deus quer, do que fazendo o mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 3, 18, 'Porque também Cristo sofreu uma vez pelos pecados, o justo pelos injustos; para que nos levasse a Deus. [Ele estava] , de fato, morto na carne, mas vivificado pelo Espírito,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 3, 19, 'no qual ele também foi pregar aos espíritos em prisão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 3, 20, '[Estes são] os que antigamente foram rebeldes, quando uma vez a paciência de Deus aguardava nos dias de Noé, enquanto era preparada a arca. Nela, poucas almas (isto é, oito) foram salvas por meio da água.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 3, 21, 'Esta é uma representação do batismo, que agora também nos salva, não como remoção da sujeira do corpo, mas sim como o pedido de boa consciência a Deus, por meio da ressurreição de Jesus Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 3, 22, 'Ele está à direita de Deus, depois de haver subido ao céu; e os anjos, as autoridades, e os poderes estão sob o seu comando.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 4, 1, 'Visto que Cristo sofreu por nós na carne, armai-vos também com o mesmo modo de pensar, pois quem sofreu na carne terminou com o pecado;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 4, 2, 'para que, no resto do tempo na carne, não viva mais segundo os maus desejos humanos, mas sim segundo a vontade de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 4, 3, 'Pois já basta, no tempo passado da vida, termos feito a vontade dos pagãos, e andado em promiscuidades, desejos maliciosos, bebedeiras, orgias, festas de embriaguez, e abomináveis idolatrias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 4, 4, 'Como eles estranham vós não agirdes como eles, que correm em busca da extrema devassidão, por isso falam mal de vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 4, 5, 'Eles terão de prestar contas ao que está pronto para julgar os vivos e os mortos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 4, 6, 'Pois por isso o evangelho também foi pregado aos mortos, para que, mesmo que tenham sido julgados na carne segundo os critérios humanos, vivam em espírito segundo os critérios de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 4, 7, 'O fim de todas as coisas está próximo; portanto sede sóbrios, e vigiai em orações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 4, 8, 'Mas, acima de tudo, tende fervoroso amor uns para com os outros; porque o amor cobrirá uma multidão de pecados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 4, 9, 'Proporcionai hospitalidade uns aos outros, sem murmurações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 4, 10, 'Cada um sirva aos outros segundo o dom que recebeu, como bons administradores da variada graça de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 4, 11, 'Se alguém fala, que seja como as palavras de Deus; se alguém serve, [que sirva] segundo a força que Deus dá; a fim de que em tudo Deus seja glorificado por meio de Jesus Cristo. E a ele pertencem a glória e o poder para todo o sempre, Amém!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 4, 12, 'Amados, não estranheis o fogo ardente que vem sobre vós para vos provar, como se algo estranho estivesse vos acontecendo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 4, 13, 'Em vez disso, alegrai-vos em serdes participantes das aflições de Cristo; para que, também na revelação de sua glória vos alegreis com júbilo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 4, 14, 'Se vós sois insultados por causa do nome de Cristo, benditos sois; porque o Espírito da glória e de Deus repousa sobre vós; o qual por eles é insultado, mas por vós é glorificado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 4, 15, 'Porém nenhum de vós sofra como homicida, ladrão, malfeitor, ou como alguém que se intromete em assuntos alheios;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 4, 16, 'Mas se [sofre] como cristão, não se envergonhe; ao contrário, glorifique a Deus por isso;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 4, 17, 'Pois já é tempo do julgamento começar pela casa de Deus; e se é primeiro conosco, qual será o fim daqueles que são desobedientes ao Evangelho de Deus?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 4, 18, 'E se o justo se salva com dificuldade, em que situação aparecerá o ímpio e pecador?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 4, 19, 'Portanto, os que sofrem segundo a vontade de Deus, confiem suas almas ao fiel Criador, fazendo o bem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 5, 1, 'Aos anciãos da igreja que estão entre vós, eu, que sou ancião como eles, e testemunha dos sofrimentos de Cristo, e participante da glória que se revelará, seriamente peço:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 5, 2, 'Pastoreai o rebanho de Deus que está entre vós, não por obrigação, mas sim voluntariamente; não por ganância, mas sim com sincera prontidão;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 5, 3, 'nem como que dominando os que estão aos vossos cuidados, mas sim como exemplos ao rebanho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 5, 4, 'E quando o Pastor Principal aparecer, vós recebereis a indestrutível coroa da glória.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 5, 5, 'Semelhantemente vós, jovens, sede sujeitos aos anciãos; e todos vós sede sujeitos uns aos outros, revestidos de humildade; pois: Deus resiste aos soberbos, mas dá graça aos humildes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 5, 6, 'Humilhai-vos, pois, debaixo da poderosa mão de Deus, para que ele vos exalte no tempo adequado,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 5, 7, 'lançando sobre ele toda a vossa ansiedade; porque ele tem cuidado de vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 5, 8, 'Sede sóbrios! Vigiai! Pois o vosso adversário, o diabo, anda ao redor, rugindo como um leão, buscando a quem possa devorar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 5, 9, 'Resisti a ele, firmes na fé; sabendo que as mesmas aflições acontecem com os vossos irmãos no mundo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 5, 10, 'E o Deus de toda graça, que nos chamou para a sua eterna glória em Cristo Jesus, depois de sofrerdes um pouco, ele vos aperfeiçoe, confirme, fortifique, e estabeleça fundamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 5, 11, 'A ele sejam a glória e o poder para todo o sempre. Amém!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 5, 12, 'Por Silvano, vosso fiel irmão, como o considero, eu vos escrevi brevemente, exortando e dando testemunho de que esta é a verdadeira graça de Deus, na qual estais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 5, 13, 'Saúda-vos a [igreja] escolhida convosco, que está na Babilônia, e também o meu filho Marcos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 60, '1 Pedro', '1Pe', 5, 14, 'Saudai-vos uns aos outros com beijo de amor. A paz seja com todos vós que estais em Cristo Jesus. Amém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 1, 1, 'Simão Pedro, servo e apóstolo de Jesus Cristo, aos que obtiveram conosco a igualmente preciosa fé pela justiça de nosso Deus e Salvador Jesus Cristo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 1, 2, 'Graça e paz vos seja multiplicada pelo conhecimento de Deus, e de Jesus nosso Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 1, 3, 'Como seu divino poder ele tem nos dado tudo o que [pertence] à vida e à devoção divina, por meio do conhecimento daquele que nos chamou à glória e virtude;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 1, 4, 'Pelas quais nos são dadas grandíssimas e preciosas promessas, para que por meio delas sejais participantes da natureza divina, tendo escapado da corrupção que há no mundo pelo mau desejo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 1, 5, 'E por isso mesmo, pondo todo o empenho, acrescentai a vossa fé virtude; e à virtude, conhecimento;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 1, 6, 'E ao conhecimento, domínio próprio; e ao domínio próprio, paciência; e à paciência, devoção divina;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 1, 7, 'E à devoção divina, amor fraternal; e ao amor fraternal, amor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 1, 8, 'Porque se em vós existirem e abundarem estas coisas, elas não vos deixarão ociosos nem estéreis no conhecimento de nosso Senhor Jesus Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 1, 9, 'Porque aquele em quem não há estas coisas é cego, nada vendo de longe, tendo se esquecido da purificação de seus antigos pecados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 1, 10, 'Portanto, irmãos, procurai ainda mais confirmar vosso chamamento e escolha [da parte de Deus] ; porque fazendo isso nunca tropeçareis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 1, 11, 'Porque assim vos será abundantemente fornecida a entrada no reino eterno de nosso Senhor e Salvador Jesus Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 1, 12, 'Por isso eu não deixarei de sempre vos relembrar destas coisas, ainda que [as] saibais, e estejais firmes na verdade presente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 1, 13, 'E eu considero justo, enquanto eu estiver neste tabernáculo, de vos despertar com relembranças;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 1, 14, 'Sabendo que breve está a saída do meu meu tabernáculo, conforme também nosso Senhor Jesus Cristo tem revelado a mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 1, 15, 'Mas também procurarei que depois de minha partida vós sejais capazes de ter lembrança destas coisas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 1, 16, 'Porque nós não vos anunciamos o poder e vinda de nosso Senhor Jesus Cristo seguindo mitos criados pela inteligência humana, mas sim como testemunhas oculares de sua grandiosidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 1, 17, 'Porque de Deus Pai ele recebeu honra e glória, tendo sido lhe enviada tal voz de magnífica glória: Este é meu amado Filho, em quem me agrado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 1, 18, 'E nós ouvimos esta voz enviada do Céu, estando nós com ele no santo monte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 1, 19, 'E temos a muito confiável palavra dos profetas; a qual vós fazeis bem ao prestardes atenção, como a uma luz que ilumina em lugar escuro, até que o dia clareie e a estrela da manhã se levante em vossos corações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 1, 20, 'Sabendo primeiramente isto: que nenhuma profecia da Escritura é de interpretação particular.')
